/bin/bash -lc "curl -fsSL 'https://api.anaconda.org/package/bioconda/statsmodels' | python -c 'import json,sys; d=json.load(sys.stdin); vals=[]; seen=set();
for f in d.get(\"files\",[]):
 b=f.get(\"basename\",\"\");
 if b.endswith(\".tar.bz2\") and \"/linux-64/\" in b:
  x=b.rsplit(\"/\",1)[-1][:-8];
  if x not in seen: seen.add(x); vals.append(x)
print(\"\\n\".join(vals[-30:]))'"

